function invalidate(){revision++;result=null;selected=null;$('results').hidden=true;$('result-empty').hidden=false;$('solve-status').textContent='Los datos cambiaron. Calcula una nueva distribución.';save();studio?.invalidate();}
function download(name,data,type='application/json'){const blob=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function page(id){window.AnaquelCentro?.[id==='centro'?'start':'stop']?.();window.AnaquelMonitor?.[id==='monitoreo'?'start':'stop']?.();if(!$(id)?.classList.contains('page'))id='inicio';document.querySelectorAll('.page').forEach(p=>p.hidden=p.id!==id);document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n.dataset.page===id));$('top-title').textContent=document.querySelector(`.nav[data-page="${id}"]`).textContent.trim();history.replaceState(null,'',`#${id}`);window.scrollTo({top:0,behavior:'instant'});if(id!=='camaras')document.body.classList.remove('theater');if(id==='informe')studio?.renderReport();clearNotice();}
