const fields=[['sku','SKU','text'],['name','Producto','text'],['width','Ancho (cm)','number'],['price','Precio (S/)','number'],['cost','Costo variable (S/)','number'],['stock','Stock','number'],['demand','Demanda / periodo','number'],['units_per_facing','Ventas / frente','number'],['appeal','Atractivo','number'],['min_faces','Frentes mín.','number'],['max_faces','Frentes máx.','number'],['current_shelf','Anaquel actual','select'],['current_faces','Frentes actuales','number']];
