function renderTable(id,rows,columns,kind){$(id).innerHTML=`<table><thead><tr>${columns.map(c=>`<th scope="col">${c[1]}</th>`).join('')}<th>Eliminar</th></tr></thead><tbody>${rows.map((p,i)=>`<tr>${columns.map(([key,label,type])=>`<td>${type==='select'?`<select data-kind="${kind}" data-row="${i}" data-field="${key}" aria-label="${label} ${i+1}"><option value="">Sin asignar</option>${project.anaqueles.map(s=>`<option ${p[key]===s.name?'selected':''} value="${esc(s.name)}">${esc(s.name)}</option>`).join('')}</select>`:`<input data-kind="${kind}" data-row="${i}" data-field="${key}" aria-label="${label} ${i+1}" type="${type}" ${type==='number'?'min="0" step="any"':'maxlength="100"'} value="${esc(p[key])}">`}</td>`).join('')}<td><button class="remove" data-remove="${kind}" data-row="${i}" aria-label="Eliminar ${esc(p.name)}">×</button></td></tr>`).join('')}</tbody></table>`;}
function renderCatalog(){renderTable('product-table',project.productos,fields,'productos');renderTable('shelf-table',project.anaqueles,shelfFields,'anaqueles');$('origin').value=project.procedencia||'';$('period').value=project.periodo||'Semana';$('budget').value=project.presupuesto;renderShelfOptions();updateBadge();studio?.refresh();}
function renderShelfOptions(){const prev=$('target-shelf').value;$('target-shelf').innerHTML=project.anaqueles.map((s,i)=>`<option value="${i}">${esc(s.name)}</option>`).join('');if(project.anaqueles[prev])$('target-shelf').value=prev;}
for(const id of ['product-table','shelf-table']){
 $(id).addEventListener('change',e=>{const t=e.target;if(!t.dataset.field)return;const {kind,row,field}=t.dataset,old=project[kind][row][field];project[kind][row][field]=t.type==='number'?t.value===''?NaN:Number(t.value):t.value;if(kind==='anaqueles'&&field==='name'){project.productos.forEach(p=>{if(p.current_shelf===old)p.current_shelf=t.value;});renderTable('product-table',project.productos,fields,'productos');renderShelfOptions();}invalidate();});
 $(id).addEventListener('click',e=>{const t=e.target.closest('[data-remove]');if(!t)return;const kind=t.dataset.remove;if(project[kind].length===1)return notify('Conserva al menos un registro.',true);const removed=project[kind].splice(Number(t.dataset.row),1)[0];if(kind==='anaqueles')project.productos.forEach(p=>{if(p.current_shelf===removed.name){p.current_shelf='';p.current_faces=0;}});invalidate();renderCatalog();});
}
for(const [id,key] of [['origin','procedencia'],['period','periodo'],['budget','presupuesto']])$(id).onchange=()=>{project[key]=id==='budget'?Number($('budget').value):$(id).value;invalidate();};
$('add-product').onclick=()=>{if(project.productos.length>=40)return notify('Máximo 40 productos.',true);let n=project.productos.length+1;while(project.productos.some(p=>p.sku===`P${n}`))n++;project.productos.push({sku:`P${n}`,name:'Nuevo producto',width:10,price:0,cost:0,stock:0,demand:0,units_per_facing:1,appeal:1,min_faces:0,max_faces:4,current_shelf:'',current_faces:0});invalidate();renderCatalog();};
$('add-shelf').onclick=()=>{if(project.anaqueles.length>=8)return notify('Máximo 8 anaqueles.',true);let n=project.anaqueles.length+1;while(project.anaqueles.some(s=>s.name===`Anaquel ${n}`))n++;project.anaqueles.push({name:`Anaquel ${n}`,capacity:90,visibility:1,activity:0});invalidate();renderCatalog();};
$('export-project').onclick=()=>{try{validate(project);download('AnaquelLab-proyecto.json',project);}catch(e){notify(e.message,true);}};
$('import-project').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>2e6)throw Error('El proyecto excede 2 MB.');const p=JSON.parse(await f.text());validate(p);project=p;invalidate();renderCatalog();notify('Proyecto importado.');}catch(e){notify(`No se importó el proyecto: ${e.message}`,true);}finally{e.target.value='';}};
$('load-demo').onclick=async()=>{if(!confirm('¿Reemplazar los datos actuales por el histórico de Moquegua 2 (6–18 nov)? Exporta antes si quieres conservarlos.'))return;project=await(await fetch('./ejemplo.json')).json();invalidate();renderCatalog();notify('Histórico 6–18 nov cargado (días 13–18 estimados). Reemplaza lo estimado con datos reales cuando los tengas.');};
function resetMeasurement(){studio?.resetVision();measuring=false;meter.reset();measurementContext=null;$('measure-start').disabled=false;$('measure-stop').disabled=true;$('apply-activity').disabled=true;$('motion-status').textContent='Sin iniciar';renderMeasurement();}
function renderMeasurement(){const r=meter.result();$('activity-value').innerHTML=`${r.duration?num(r.activity*100,1)+'%':'—'}<small>del tiempo con movimiento</small>`;$('activity-bar').style.width=`${r.activity*100}%`;$('duration-value').textContent=`${num(r.duration,1)} s`;$('episode-value').textContent=r.episodes;$('apply-activity').disabled=measuring||r.duration<10||$('vision-mode').value==='people';}
function updateSources(){const previous=$('analysis-source').value;$('analysis-source').innerHTML='<option value="file">Video de mi equipo</option>'+(stream?cameraSettings.map((c,i)=>c.enabled?`<option value="${i}">Cámara ${esc(c.label)} · pestaña en vivo</option>`:'').join(''):'');if([...$('analysis-source').options].some(o=>o.value===previous))$('analysis-source').value=previous;else{resetMeasurement();roi=allROI();}}
function buildCameras(){const count=gridRows*gridCols;cameraSettings=Array.from({length:count},(_,i)=>cameraSettings[i]||{label:channels[i]||String(i+1).padStart(2,'0'),enabled:true});$('camera-selection').innerHTML=cameraSettings.map((c,i)=>`<label><input type="checkbox" data-camera="${i}" ${c.enabled?'checked':''}> Cámara ${esc(c.label)}</label>`).join('');$('camera-grid').innerHTML=cameraSettings.map((c,i)=>`<article class="camera-card" id="card-${i}" ${c.enabled?'':'hidden'}><canvas id="camera-${i}" width="480" height="270" aria-label="Vista de cámara ${esc(c.label)}"></canvas><div class="camera-label"><span>Cámara ${esc(c.label)}</span><span>VISTA COMPARTIDA</span></div></article>`).join('');$('camera-names').value=cameraSettings.map(c=>c.label).join(', ');updateCount();updateSources();}
$('camera-names').onchange=()=>{const names=$('camera-names').value.split(',').map(s=>s.trim());if(names.length!==gridRows*gridCols||names.some(s=>!s||s.length>30)||new Set(names).size!==names.length)return notify('Escribe un nombre único por cuadro, separado por comas.',true);cameraSettings=cameraSettings.map((c,i)=>({...c,label:names[i]}));resetMeasurement();buildCameras();};
function updateCount(){setTimeout(()=>window.AnaquelLab?.live?.emit?.(),0);const n=stream?cameraSettings.filter(c=>c.enabled).length:0;$('camera-count').innerHTML=`${n} <small>cámaras seleccionadas</small>`;studio?.cameras(n,!!stream);}
$('camera-selection').onchange=e=>{const i=Number(e.target.dataset.camera);if(!Number.isInteger(i))return;cameraSettings[i].enabled=e.target.checked;$(`card-${i}`).hidden=!e.target.checked;updateCount();updateSources();};
function stopLive(){if(stream)stream.getTracks().forEach(t=>t.stop());stream=null;live.srcObject=null;liveFrame=0;$('live-state').textContent='● Sin conexión';$('live-state').classList.remove('live');$('live-tools').hidden=true;$('live-empty').hidden=false;$('connect').hidden=false;$('disconnect').hidden=true;$('connection-label').textContent='Pendiente';if($('analysis-source').value!=='file')resetMeasurement();updateSources();updateCount();}
$('connect').onclick=async()=>{clearNotice();if(!navigator.mediaDevices?.getDisplayMedia)return notify('Abre esta web en Chrome o Edge de escritorio para compartir la pestaña de Hik-Connect.',true);$('connect').disabled=true;$('connect').textContent='Elige la pestaña en el permiso…';try{const next=await navigator.mediaDevices.getDisplayMedia({video:{displaySurface:'browser',frameRate:{ideal:10,max:15}},audio:false,selfBrowserSurface:'exclude',surfaceSwitching:'include'});stopLive();stream=next;const track=stream.getVideoTracks()[0];track.addEventListener('ended',()=>{stopLive();notify('La vista en vivo se desconectó.');});track.addEventListener('mute',()=>{$('live-state').textContent='● Fuente pausada';});track.addEventListener('unmute',()=>{$('live-state').textContent='● Pestaña compartida';});live.srcObject=stream;await live.play();crop=allROI();syncCrop();$('capture-details').open=true;$('live-state').textContent='● Pestaña compartida';$('live-state').classList.add('live');$('connection-label').textContent='Pestaña en vivo';$('live-empty').hidden=true;$('live-tools').hidden=false;$('connect').hidden=true;$('disconnect').hidden=false;buildCameras();notify('Selecciona el rectángulo que contiene el mosaico de cámaras.');}catch(e){stopLive();notify(e.name==='NotAllowedError'?'No se compartió ninguna pestaña. Pulsa Conectar y elige la vista de Hik-Connect.':`No se pudo iniciar la vista: ${e.message}`,true);}finally{$('connect').disabled=false;$('connect').textContent='2. Conectar vista en vivo';}};
$('disconnect').onclick=stopLive;
for(const id of ['grid-rows','grid-cols'])$(id).onchange=()=>{gridRows=Number($('grid-rows').value);gridCols=Number($('grid-cols').value);resetMeasurement();buildCameras();};
$('crop-reset').onclick=()=>{crop=allROI();syncCrop();resetMeasurement();};$('crop-done').onclick=()=>{$('capture-details').open=false;notify('Mosaico aplicado. Desmarca las cámaras que no tengan imagen.');};
function dragROI(canvas,get,set){let start=null;const pos=e=>{const r=canvas.getBoundingClientRect();return {x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))};};canvas.onpointerdown=e=>{if(canvas.id==='capture-canvas'&&!stream)return;start=pos(e);canvas.setPointerCapture(e.pointerId);resetMeasurement();};canvas.onpointermove=e=>{if(!start)return;const p=pos(e),r={x:Math.min(start.x,p.x),y:Math.min(start.y,p.y),w:Math.abs(start.x-p.x),h:Math.abs(start.y-p.y)};if(r.w>.015&&r.h>.015)set(r);};canvas.onpointerup=()=>{start=null;};canvas.onpointercancel=()=>{start=null;};}
dragROI($('capture-canvas'),()=>crop,r=>{crop=r;syncCrop();});dragROI($('analysis-canvas'),()=>roi,r=>roi=r);
function overlay(ctx,rect,w,h){ctx.strokeStyle='#c8ee8e';ctx.lineWidth=3;ctx.strokeRect(rect.x*w,rect.y*h,rect.w*w,rect.h*h);}
function drawCameras(){if(!stream||live.readyState<2||!live.videoWidth||stream.getVideoTracks()[0].muted)return;const cap=$('capture-canvas');const h=Math.round(960*live.videoHeight/live.videoWidth);if(cap.height!==h)cap.height=h;const cx=cap.getContext('2d');cx.drawImage(live,0,0,cap.width,cap.height);overlay(cx,crop,cap.width,cap.height);cameraSettings.forEach((c,i)=>{if(!c.enabled)return;const can=$(`camera-${i}`),ctx=can.getContext('2d',{willReadFrequently:true});ctx.drawImage(live,...cropPixels(cropCell(crop,i,gridRows,gridCols),live.videoWidth,live.videoHeight),0,0,480,270);let blank=false;if($('hide-blank').checked){const data=ctx.getImageData(120,68,240,135).data;let bright=0;for(let k=0;k<data.length;k+=16)if(data[k]+data[k+1]+data[k+2]>45)bright++;blank=bright/(data.length/16)<.015;}$(`card-${i}`).hidden=blank;});}
function analysisFrame(){const source=$('analysis-source').value;if(source==='file'){if(fileVideo.readyState<2||!fileVideo.videoWidth)return false;frameCanvas.height=Math.max(1,Math.round(640*fileVideo.videoHeight/fileVideo.videoWidth));fx.drawImage(fileVideo,0,0,frameCanvas.width,frameCanvas.height);return true;}if(!stream||live.readyState<2||stream.getVideoTracks()[0].muted)return false;const i=Number(source);if(!cameraSettings[i]?.enabled)return false;const r=cropCell(crop,i,gridRows,gridCols),aspect=(r.w*live.videoWidth)/(r.h*live.videoHeight);frameCanvas.height=Math.max(1,Math.round(640/aspect));fx.drawImage(live,...cropPixels(r,live.videoWidth,live.videoHeight),0,0,frameCanvas.width,frameCanvas.height);return true;}
function drawAnalysis(now){
 const available=analysisFrame(),can=$('analysis-canvas'),ctx=can.getContext('2d');$('analysis-empty').hidden=available;
 if(!available){ctx.clearRect(0,0,can.width,can.height);return;}
 if(can.height!==frameCanvas.height)can.height=frameCanvas.height;
 ctx.drawImage(frameCanvas,0,0);overlay(ctx,roi,can.width,can.height);studio?.paint(ctx,can.width,can.height);
 if(measuring){const isFile=$('analysis-source').value==='file';if(isFile&&(fileVideo.paused||fileVideo.seeking))return;
 const time=isFile?fileVideo.currentTime:now/1000;
 sx.drawImage(frameCanvas,...cropPixels(roi,frameCanvas.width,frameCanvas.height),0,0,160,90);
 const r=meter.sample(sx.getImageData(0,0,160,90).data,time);
 if($('vision-mode').value==='people'){studio.onFrame(frameCanvas,time,roi);$('motion-status').textContent='Detectando personas y permanencia en zona…';}
 else $('motion-status').textContent=r.duration?'Midiendo movimiento…':'Preparando imagen (3 segundos)…';renderMeasurement();
 }
}
function tick(now){if(now-lastPaint>=200){lastPaint=now;drawCameras();drawAnalysis(now);}requestAnimationFrame(tick);}requestAnimationFrame(tick);
$('analysis-source').onchange=()=>{resetMeasurement();roi=allROI();fileVideo.pause();};
$('video-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;resetMeasurement();fileVideo.pause();if(fileUrl)URL.revokeObjectURL(fileUrl);fileUrl=URL.createObjectURL(f);videoName=f.name;fileVideo.src=fileUrl;fileVideo.load();$('analysis-source').value='file';roi=allROI();fileVideo.onloadeddata=()=>notify(`Video abierto: ${f.name}`);fileVideo.onerror=()=>notify('El navegador no puede leer este video. Usa MP4 con video H.264 o WebM.',true);e.target.value='';};
$('roi-reset').onclick=()=>{roi=allROI();resetMeasurement();};
$('measure-start').onclick=async()=>{
 clearNotice();if(!analysisFrame())return notify('Primero conecta una cámara o abre un video.',true);
 const threshold=Number($('sensitivity').value),fraction=Number($('pixel-area').value)/100;
 if(!Number.isFinite(threshold)||threshold<1||threshold>255||!Number.isFinite(fraction)||fraction<.001||fraction>1)return notify('Revisa los umbrales de medición.',true);
 $('measure-start').disabled=true;
 try{
  const people=$('vision-mode').value==='people',options=people?await studio.prepareVision():null;
  if(!analysisFrame())throw Error('La fuente de imagen se desconectó.');
  meter=new MotionMeter({threshold,minFraction:fraction});
  const isFile=$('analysis-source').value==='file';if(isFile){fileVideo.currentTime=0;await fileVideo.play();}
  measurementContext={fuente:isFile?`Archivo: ${videoName}`:`Pestaña compartida · Cámara ${cameraSettings[Number($('analysis-source').value)].label}`,zona:structuredClone(roi),fecha:new Date().toISOString(),umbral:threshold,area_minima:fraction,startTime:isFile?0:performance.now()/1000};
  if(people)studio.beginVision(measurementContext,options);
  measuring=true;$('measure-stop').disabled=false;$('apply-activity').disabled=true;$('motion-status').textContent='Iniciando observación…';
 }catch(e){$('measure-start').disabled=false;$('detector-state').textContent='Detección sin iniciar';notify(e.message,true);}
};
function stopMeasurement(){if(!measuring)return;measuring=false;studio?.endVision();fileVideo.pause();$('measure-start').disabled=false;$('measure-stop').disabled=true;$('motion-status').textContent=meter.result().duration<10?'Medición corta: se necesitan al menos 10 segundos válidos.':'Medición terminada';renderMeasurement();}
$('measure-stop').onclick=stopMeasurement;fileVideo.onended=stopMeasurement;
document.addEventListener('visibilitychange',()=>{if(document.hidden&&measuring){stopMeasurement();notify('Medición detenida al salir de la pestaña para evitar intervalos incompletos.');}});
$('apply-activity').onclick=()=>{const r=meter.result(),s=project.anaqueles[Number($('target-shelf').value)];if(measuring||r.duration<10||!s)return; s.activity=r.activity;project.mediciones=project.mediciones||[];project.mediciones.push({...measurementContext,anaquel:s.name,...r,metodo:'Diferencia de luminancia entre fotogramas'});if(project.mediciones.length>500)project.mediciones.shift();invalidate();renderCatalog();notify(`Actividad de ${s.name} actualizada a ${num(r.activity*100,1)}%.`);};
$('weight').oninput=()=>{$('weight-margin').textContent=`${$('weight').value}%`;$('weight-activity').textContent=`${100-Number($('weight').value)}%`;if(result)$('solve-status').textContent='El peso cambió. Calcula de nuevo para aplicarlo.';};
function renderResult(r){selected=r;$('results').hidden=false;$('result-empty').hidden=true;$('result-margin').textContent=money(r.margen);$('result-activity').textContent=num(r.actividad);$('result-capital').textContent=money(r.filas.reduce((s,x)=>s+x.capital,0));$('baseline-margin').textContent=result.base?`Distribución actual: ${money(result.base.margen)}`:'Distribución actual no comparable: revisa su factibilidad.';$('result-table').innerHTML=`<table><thead><tr><th>Producto</th><th>Anaquel</th><th>Frentes</th><th>Ancho (cm)</th><th>Ventas estimadas</th><th>Margen estimado</th></tr></thead><tbody>${r.filas.map(x=>`<tr><td>${esc(x.producto)}</td><td>${esc(x.anaquel)}</td><td>${x.frentes}</td><td>${num(x.ancho_cm)}</td><td>${num(x.ventas_estimadas)}</td><td>${money(x.margen_estimado)}</td></tr>`).join('')}</tbody></table>`;const colors=['#dce8c0','#c4dfcf','#f0d8af','#cadad4','#e3ddbe','#bad6bd','#e6cbbb','#d2d4e3'];$('planogram').innerHTML=project.anaqueles.map(s=>{const rows=r.filas.filter(x=>x.anaquel===s.name),used=rows.reduce((v,x)=>v+x.ancho_cm,0);return `<div class="shelf-title"><b>${esc(s.name)}</b><span>${num(used)} / ${num(s.capacity)} cm</span></div><div class="shelfbar">${rows.map(x=>`<div class="shelfitem" style="width:${x.ancho_cm/s.capacity*100}%;background:${colors[project.productos.findIndex(p=>p.sku===x.sku)%colors.length]}" title="${esc(x.producto)}: ${x.frentes} frentes"><span>${esc(x.producto)}</span><b>${x.frentes} fr.</b></div>`).join('')}</div>`;}).join('');$('frontier').innerHTML=[result.elegido,...result.frontera].map((x,i)=>`<button class="alternative ${r===x?'selected':''}" data-alternative="${i}">${esc(x.nombre)}<b>${money(x.margen)}</b><span>Interacción: ${num(x.actividad)}</span></button>`).join('');studio?.result(result,r);}
$('frontier').onclick=e=>{const b=e.target.closest('[data-alternative]');if(b)renderResult([result.elegido,...result.frontera][Number(b.dataset.alternative)]);};
$('run').onclick=async()=>{if(busy)return;clearNotice();try{validate(project);const faltan=[...project.productos.filter(p=>p.price<=0||p.cost<=0||p.stock<=0||p.demand<=0||p.units_per_facing<=0).map(p=>p.name),...project.anaqueles.filter(s=>s.capacity<=1).map(s=>'anaquel '+s.name)];if(project.presupuesto<=0||faltan.length)throw Error('Faltan datos reales para optimizar: '+(project.presupuesto<=0?'presupuesto; ':'')+faltan.slice(0,6).join(', ')+(faltan.length>6?'…':'')+'. Complétalos en «Productos y anaqueles».');busy=true;$('run').disabled=true;$('results').hidden=true;$('result-empty').hidden=false;const snapshot=structuredClone(project),startRevision=revision,weight=Number($('weight').value)/100;$('solve-status').textContent='Cargando el motor de programación entera…';if(!solverPromise)solverPromise=GLPK().catch(e=>{solverPromise=null;throw e;});const solver=await solverPromise;const calculated=await new Optimizer(snapshot,solver).run(weight,text=>$('solve-status').textContent=text);if(revision!==startRevision)throw Error('Los datos cambiaron durante el cálculo. Vuelve a calcular.');result={...calculated,datos:snapshot};renderResult(result.elegido);$('solve-status').textContent=`Óptimo del modelo certificado · ${snapshot.periodo||'Periodo'} · Peso de margen ${Math.round(weight*100)}% · ${snapshot.procedencia||'Origen no indicado'}`;notify('Distribución calculada y restricciones comprobadas.');}catch(e){result=null;selected=null;$('results').hidden=true;$('result-empty').hidden=false;$('solve-status').textContent='No se generó una recomendación.';notify(e.message,true);}finally{busy=false;$('run').disabled=false;}};
$('export-result').onclick=()=>{if(result)download('AnaquelLab-informe.json',{...result,seleccionado:selected,advertencia:'Estimaciones del modelo; actividad visual no equivale a personas o ventas observadas.'});};
const csvCell=v=>`"${String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')}"`;
$('export-csv').onclick=()=>{if(!selected)return;const cols=['sku','producto','anaquel','frentes','ancho_cm','capital','ventas_estimadas','margen_estimado','actividad_indice'];download('AnaquelLab-distribucion.csv','\uFEFF'+[cols,...selected.filas.map(x=>cols.map(k=>x[k]))].map(r=>r.map(csvCell).join(';')).join('\r\n'),'text/csv;charset=utf-8');};
window.addEventListener('beforeunload',()=>{stream?.getTracks().forEach(t=>t.stop());if(fileUrl)URL.revokeObjectURL(fileUrl);});
try {const saved=localStorage.getItem('anaquellab.project.v2');if(saved){try{project=validate(JSON.parse(saved));}catch{notify('Los datos guardados no son válidos. Se cargó el ejemplo.',true);}}}catch{/* Private mode can disable storage. */}
try {if(!project)project=validate(await(await fetch('./ejemplo.json')).json());studio=new ResearchUI({getProject:()=>project,changed:()=>{invalidate();renderCatalog();},notify,download,navigate:page});renderCatalog();initExperience({navigate:page});page(location.hash.slice(1)||'inicio');}catch(e){notify(`No se pudo abrir el proyecto: ${e.message}`,true);}

function syncCrop(){for(const k of ['x','y','w','h'])$('crop-'+k).value=(crop[k]*100).toFixed(1);}
$('crop-apply').onclick=()=>{const r=Object.fromEntries(['x','y','w','h'].map(k=>[k,Number($('crop-'+k).value)/100]));if(Object.values(r).some(v=>!Number.isFinite(v))||r.x<0||r.y<0||r.w<=.01||r.h<=.01||r.x+r.w>1.001||r.y+r.h>1.001)return notify('El recorte debe quedar dentro del 100% de la imagen.',true);crop=r;resetMeasurement();notify('Recorte del mosaico actualizado.');};
$('camera-theater').onclick=()=>{const on=document.body.classList.toggle('theater');$('camera-theater').textContent=on?'Salir del modo amplio':'Ampliar cámaras';};
syncCrop();

var autoRun=false;const liveSubs=[];
window.AnaquelLab={getProject:()=>project,getSelected:()=>selected,notify,live:{connected:()=>!!stream,cameras:()=>cameraSettings.map((c,i)=>({i,label:c.label,enabled:c.enabled})),canvas:i=>$('camera-'+i),connect:()=>$('connect').click(),disconnect:()=>stopLive(),subscribe:f=>liveSubs.push(f),emit:()=>liveSubs.forEach(f=>{try{f();}catch{}})}};
setTimeout(()=>{try{if(project&&!result&&!busy){autoRun=true;$('run').click();setTimeout(()=>{autoRun=false;},8000);}}catch{}},900);
